def load_json(path, default):
    if not os.path.exists(path):
        return default
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as e:
        print(f"Could not load {path}: {e}")
        return default


def save_json(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=4)
    os.replace(tmp, path)


def load_data():
    return load_json(DATA_FILE, {})


def save_data(data):
    save_json(DATA_FILE, data)


def load_admins():
    admins = [str(INITIAL_ADMIN_ID)]
    loaded = load_json(ADMINS_FILE, [])
    if isinstance(loaded, list):
        for aid in loaded:
            aid = str(aid)
            if aid not in admins:
                admins.append(aid)
    return admins


def save_admins(admins):
    unique = []
    for aid in [INITIAL_ADMIN_ID] + list(admins):
        aid = str(aid)
        if aid not in unique:
            unique.append(aid)
    save_json(ADMINS_FILE, unique)


def is_admin(user_id):
    return str(user_id) in load_admins()


def load_channels():
    default = [
        {
            "name": "@hackwhatandetc",
            "url": "https://t.me/hackwhatandetc",
            "id": "@hackwhatandetc",
        },
        {
            "name": "@hackwhatandetcb",
            "url": "https://t.me/hackwhatandetcb",
            "id": "@hackwhatandetcb",
        },
    ]

    if not os.path.exists(CHANNELS_FILE):
        save_json(CHANNELS_FILE, default)
        return default

    channels = load_json(CHANNELS_FILE, default)
    return channels if isinstance(channels, list) else default


def save_channels(channels):
    save_json(CHANNELS_FILE, channels)


def check_user_membership(user_id):
    channels = load_channels()

    for ch in channels:
        try:
            member = bot.get_chat_member(ch["id"], int(user_id))
            if member.status not in ("member", "administrator", "creator"):
                return False
        except Exception as e:
            print(f"Membership check failed for {ch['id']}: {e}")
            return False

    return True


