def stop_process(bot_id):
    process = active_user_processes.pop(bot_id, None)
    if not process:
        return

    try:
        process.terminate()
        process.wait(timeout=5)
    except Exception:
        try:
            process.kill()
        except Exception:
            pass


def safe_bot_filename(name):
    name = os.path.splitext(name)[0]
    cleaned = "".join(c for c in name if c.isalnum() or c in "_-")
    return cleaned or "bot"


def check_code_syntax(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            code = f.read()
        compile(code, path, "exec")
        return True, None
    except Exception as e:
        return False, str(e)


def background_expiration_checker():
    while True:
        try:
            data = load_data()
            now = time.time()
            changed = False

            for uid, user_info in list(data.items()):
                bots = user_info.get("bots", {})

                for bot_id, bot_info in list(bots.items()):
                    expire_time = bot_info.get("expire_time")

                    if expire_time and now >= expire_time:
                        stop_process(bot_id)

                        path = os.path.join(
                            USER_BOTS_DIR,
                            f"{bot_id}_bot.py",
                        )

                        if os.path.exists(path):
                            try:
                                os.remove(path)
                            except Exception as e:
                                print(f"File delete error: {e}")

                        del bots[bot_id]
                        changed = True

                        try:
                            lang = user_info.get("lang") or "dr"
                            bot.send_message(
                                int(uid),
                                "⏳ مدت زمان ربات شما به پایان رسید و ربات خاموش شد."
                                if lang != "en"
                                else "⏳ Your bot activation time has expired.",
                            )
                        except Exception:
                            pass

            if changed:
                save_data(data)

        except Exception as e:
            print(f"Expiration checker error: {e}")

        time.sleep(60)


@bot.message_handler(commands=["start"])
def start(message):
    uid = str(message.from_user.id)
    data = load_data()

    args = message.text.split()
    is_new = uid not in data

    if is_new:
        data[uid] = {
            "score": 0,
            "lang": None,
            "bots": {},
        }

        if len(args) > 1:
            referrer = args[1]

            if referrer in data and referrer != uid:
                data[referrer]["score"] = data[referrer].get("score", 0) + 5

                try:
                    ref_lang = data[referrer].get("lang") or "dr"
                    bot.send_message(
                        int(referrer),
                        TRANSLATIONS[ref_lang]["ref_bonus"],
                    )
                except Exception:
                    pass

        save_data(data)

        # Notify admins about a new user.
        for admin_id in load_admins():
            try:
                username = (
                    f"@{message.from_user.username}"
                    if message.from_user.username
                    else "ندارد"
                )

                text = (
                    "👤 کاربر جدید\n\n"
                    f"⚡ نام: {message.from_user.first_name or 'بدون نام'}\n"
                    f"🔗 یوزرنیم: {username}\n"
                    f"🆔 UserID: {uid}"
                )

                bot.send_message(int(admin_id), text)
            except Exception:
                pass

    if data[uid].get("lang") is None:
        markup = types.InlineKeyboardMarkup(row_width=2)
        markup.add(
            types.InlineKeyboardButton("دری 🇦🇫", callback_data="lang_dr"),
            types.InlineKeyboardButton("English 🇬🇧", callback_data="lang_en"),
        )

        bot.send_message(
            message.chat.id,
            TRANSLATIONS["dr"]["choose_lang"],
            reply_markup=markup,
        )
        return

    lang = data[uid]["lang"]

    if not check_user_membership(uid):
        required_membership_message(message.chat.id, lang)
        return

    send_main_menu(message.chat.id, lang)


@bot.callback_query_handler(func=lambda call: call.data.startswith("lang_"))
def set_language_callback(call):
    uid = str(call.from_user.id)
    lang = call.data.split("_", 1)[1]

    if lang not in TRANSLATIONS:
        lang = "dr"

    data = load_data()

    if uid not in data:
        data[uid] = {"score": 0, "bots": {}}

    data[uid]["lang"] = lang
    data[uid].setdefault("score", 0)
    data[uid].setdefault("bots", {})

    save_data(data)

    bot.answer_callback_query(call.id, "✅ زبان ذخیره شد." if lang == "dr" else "✅ Language saved.")

    try:
        bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception:
        pass

    if not check_user_membership(uid):
        required_membership_message(call.message.chat.id, lang)
        return

    send_main_menu(call.message.chat.id, lang)


