@bot.callback_query_handler(func=lambda call: call.data.startswith("plan_"))
def select_plan_callback(call):
    uid = str(call.from_user.id)
    data = load_data()
    lang = data.get(uid, {}).get("lang") or "dr"

    duration_map = {
        "plan_24h": 24 * 3600,
        "plan_7d": 7 * 24 * 3600,
        "plan_14d": 14 * 24 * 3600,
        "plan_30d": 30 * 24 * 3600,
    }

    cost_map = {
        "plan_24h": 50,
        "plan_7d": 350,
        "plan_14d": 700,
        "plan_30d": 1500,
    }

    plan = call.data
    if plan not in duration_map:
        bot.answer_callback_query(call.id, "❌ پلن نامعتبر است.", show_alert=True)
        return

    cost = cost_map[plan]
    duration = duration_map[plan]
    score = data.get(uid, {}).get("score", 0)

    if score < cost:
        bot.answer_callback_query(
            call.id,
            f"❌ {cost} امتیاز لازم است.",
            show_alert=True,
        )
        return

    data[uid]["pending_cost"] = cost
    data[uid]["pending_duration"] = duration
    save_data(data)

    bot.answer_callback_query(call.id)

    msg = bot.send_message(
        call.message.chat.id,
        f"📂 فایل ربات خود را با پسوند .py ارسال کنید.\n\n"
        f"💰 هزینه: {cost} امتیاز\n"
        f"⏱ مدت: {duration // 3600} ساعت",
    )

    bot.register_next_step_handler(msg, handle_uploaded_document)


