@bot.message_handler(content_types=["document"])
def handle_uploaded_document(message):
    uid = str(message.from_user.id)
    data = load_data()
    lang = data.get(uid, {}).get("lang") or "dr"

    cost = data.get(uid, {}).get("pending_cost")
    duration = data.get(uid, {}).get("pending_duration")

    if cost is None or duration is None:
        bot.reply_to(
            message,
            "❌ ابتدا یک پلن را از «آنلاین کردن ربات» انتخاب کنید.",
        )
        return

    if data.get(uid, {}).get("score", 0) < cost:
        bot.reply_to(message, "❌ امتیاز کافی نیست.")
        return

    original_name = message.document.file_name

    if not original_name.lower().endswith(".py"):
        bot.reply_to(message, "❌ فقط فایل .py قابل قبول است.")
        return

    safe_name = safe_bot_filename(original_name)
    bot_id = f"{uid}_{safe_name}"
    path = os.path.join(USER_BOTS_DIR, f"{bot_id}_bot.py")

    try:
        file_info = bot.get_file(message.document.file_id)
        content = bot.download_file(file_info.file_path)

        with open(path, "wb") as f:
            f.write(content)

        valid, error = check_code_syntax(path)

        if not valid:
            os.remove(path)
            bot.reply_to(
                message,
                f"❌ خطای Syntax در فایل شما:\n\n{error}",
            )
            return

        # Stop an older process with the same ID.
        stop_process(bot_id)

        # WARNING:
        # Running arbitrary uploaded Python code on the same server is unsafe.
        # Use a sandbox/container with strict permissions for production.
        process = subprocess.Popen(
            ["python3", path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )

        active_user_processes[bot_id] = process

        data[uid].setdefault("bots", {})
        data[uid]["bots"][bot_id] = {
            "file_name": safe_name,
            "file_id": message.document.file_id,
            "expire_time": time.time() + duration,
        }

        data[uid]["score"] -= cost
        data[uid].pop("pending_cost", None)
        data[uid].pop("pending_duration", None)

        save_data(data)

        bot.send_message(
            message.chat.id,
            f"🚀 ربات «{safe_name}» با موفقیت اجرا شد.",
            reply_markup=get_main_menu(lang),
        )

    except Exception as e:
        if os.path.exists(path):
            try:
                os.remove(path)
            except Exception:
                pass

        bot.reply_to(message, f"❌ خطا هنگام اجرای فایل:\n{e}")


