@bot.callback_query_handler(func=lambda call: call.data.startswith("delbot:"))
def delete_bot_callback(call):
    uid = str(call.from_user.id)
    data = load_data()
    lang = data.get(uid, {}).get("lang") or "dr"

    bot_id = call.data.split(":", 1)[1]
    bots = data.get(uid, {}).get("bots", {})

    if bot_id not in bots:
        bot.answer_callback_query(call.id, "❌ ربات پیدا نشد.", show_alert=True)
        return

    stop_process(bot_id)

    path = os.path.join(USER_BOTS_DIR, f"{bot_id}_bot.py")

    if os.path.exists(path):
        try:
            os.remove(path)
        except Exception:
            pass

    name = bots[bot_id].get("file_name", bot_id)
    del bots[bot_id]
    save_data(data)

    bot.answer_callback_query(call.id, "✅ حذف شد.")
    bot.send_message(
        call.message.chat.id,
        f"🗑️ ربات «{name}» متوقف و حذف شد.",
        reply_markup=get_main_menu(lang),
    )


