@bot.callback_query_handler(func=lambda call: call.data == "admin_broadcast")
def admin_broadcast_callback(call):
    if not is_admin(call.from_user.id):
        return

    msg = bot.send_message(
        call.message.chat.id,
        "✍️ متن پیام همگانی را ارسال کنید:",
    )

    bot.register_next_step_handler(msg, perform_broadcast)


def perform_broadcast(message):
    if not is_admin(message.from_user.id):
        return

    data = load_data()
    count = 0

    for uid in data:
        try:
            bot.send_message(int(uid), message.text or "")
            count += 1
        except Exception:
            pass

    bot.reply_to(message, f"✅ پیام برای {count} کاربر ارسال شد.")


@bot.message_handler(commands=["add"])
def manage_score(message):
    if not is_admin(message.from_user.id):
        return

    args = message.text.split()

    if len(args) != 3:
        bot.reply_to(message, "/add USER_ID SCORE")
        return

    target = args[1]

    try:
        amount = int(args[2])
    except ValueError:
        bot.reply_to(message, "❌ امتیاز باید عدد باشد.")
        return

    data = load_data()

    if target not in data:
        data[target] = {
            "score": 0,
            "lang": "dr",
            "bots": {},
        }

    data[target]["score"] = data[target].get("score", 0) + amount
    save_data(data)

    bot.reply_to(
        message,
        f"✅ موجودی جدید: {data[target]['score']}",
    )


@bot.message_handler(func=lambda message: is_admin(message.from_user.id) and message.reply_to_message is not None)
def admin_reply_to_user(message):
    replied = message.reply_to_message

    if not replied.text:
        return

    target_uid = None

    for line in replied.text.splitlines():
        if "UserID:" in line:
            digits = "".join(c for c in line.split("UserID:", 1)[1] if c.isdigit())
            if digits:
                target_uid = digits
                break

    if not target_uid:
        bot.reply_to(message, "❌ UserID پیدا نشد.")
        return

    try:
        bot.send_message(
            int(target_uid),
            f"💬 پاسخ پشتیبانی:\n\n{message.text}",
        )
        bot.reply_to(message, "✅ پاسخ ارسال شد.")
    except Exception as e:
        bot.reply_to(message, f"❌ خطا: {e}")


def restore_running_bots():
    data = load_data()
    now = time.time()
    changed = False

    for uid, user_info in data.items():
        bots = user_info.get("bots", {})

        for bot_id, info in list(bots.items()):
            expire_time = info.get("expire_time", 0)

            if expire_time and now >= expire_time:
                path = os.path.join(USER_BOTS_DIR, f"{bot_id}_bot.py")

                if os.path.exists(path):
                    try:
                        os.remove(path)
                    except Exception:
                        pass

                del bots[bot_id]
                changed = True
                continue

            path = os.path.join(USER_BOTS_DIR, f"{bot_id}_bot.py")

            if os.path.exists(path):
                try:
                    process = subprocess.Popen(
                        ["python3", path],
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                    )
                    active_user_processes[bot_id] = process
                except Exception as e:
                    print(f"Could not restart {bot_id}: {e}")

    if changed:
        save_data(data)


def main():
    print("Bot Manager is starting...")

    load_admins()

    restore_running_bots()

    checker_thread = threading.Thread(
        target=background_expiration_checker,
        daemon=True,
    )
    checker_thread.start()

    # IMPORTANT:
    # Polling and webhook cannot be active at the same time.
    try:
        bot.delete_webhook(drop_pending_updates=True)
        print("Old webhook deleted.")
    except Exception as e:
        print(f"Could not delete webhook: {e}")

    print("Starting polling...")

    bot.infinity_polling(
        skip_pending=True,
        timeout=30,
        long_polling_timeout=30,
    )


if __name__ == "__main__":
    main()
